package com.shopsphere.commerce.service;
import com.shopsphere.commerce.api.CheckoutOrderResponse;
import com.shopsphere.commerce.domain.*;
import com.shopsphere.commerce.payment.*;
import com.shopsphere.commerce.repository.*;
import com.shopsphere.identity.domain.UserAccount;
import com.shopsphere.identity.repository.UserAccountRepository;
import com.shopsphere.marketplace.domain.*;
import com.shopsphere.marketplace.repository.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
@Service
public class CheckoutOrderService {
 private final UserAccountRepository users; private final CustomerAddressRepository addresses; private final CartRepository carts; private final CartItemRepository cartItems; private final InventoryRepository inventory; private final InventoryMovementRepository movements; private final OrderRepository orders; private final SellerOrderRepository sellerOrders; private final OrderItemRepository orderItems; private final PaymentRepository payments; private final OrderEventRepository events; private final PaymentGateway gateway;
 public CheckoutOrderService(UserAccountRepository users,CustomerAddressRepository addresses,CartRepository carts,CartItemRepository cartItems,InventoryRepository inventory,InventoryMovementRepository movements,OrderRepository orders,SellerOrderRepository sellerOrders,OrderItemRepository orderItems,PaymentRepository payments,OrderEventRepository events,PaymentGateway gateway){this.users=users;this.addresses=addresses;this.carts=carts;this.cartItems=cartItems;this.inventory=inventory;this.movements=movements;this.orders=orders;this.sellerOrders=sellerOrders;this.orderItems=orderItems;this.payments=payments;this.events=events;this.gateway=gateway;}
 @Transactional public CheckoutOrderResponse place(UUID userId,UUID addressId,String idempotencyKey){if(idempotencyKey==null||idempotencyKey.isBlank()||idempotencyKey.length()>80)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A valid Idempotency-Key header (1–80 characters) is required");UserAccount user=users.findByIdForUpdate(userId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Account not found"));CustomerOrder previous=orders.findByCustomer_IdAndIdempotencyKey(userId,idempotencyKey).orElse(null);if(previous!=null)return existingResponse(previous);
 CustomerAddress address=addresses.findByIdAndUser_Id(addressId,userId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Shipping address not found"));Cart cart=carts.findByUser_Id(userId).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Your cart is empty"));List<CartItem> lines=cartItems.findAllForUpdate(cart.getId());if(lines.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Your cart is empty");Map<UUID,List<CartItem>> grouped=new LinkedHashMap<>();long subtotal=0;
 for(CartItem line:lines){Listing listing=line.getListing();if(!"ACTIVE".equals(listing.getListingStatus())||!"ACTIVE".equals(listing.getProduct().getProductStatus())||!"APPROVED".equals(listing.getSeller().getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"A cart offer is no longer available; refresh your cart");if(!"INR".equals(listing.getCurrency()))throw new ResponseStatusException(HttpStatus.CONFLICT,"All items in one checkout must use INR");Inventory stock=inventory.findByListingIdForUpdate(listing.getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"Inventory is unavailable"));if(stock.getAvailableQty()<line.getQuantity())throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient stock for "+listing.getProduct().getTitle());subtotal=Math.addExact(subtotal,Math.multiplyExact(listing.getPriceMinor(),line.getQuantity()));grouped.computeIfAbsent(listing.getSeller().getId(),key->new ArrayList<>()).add(line);}
 String orderNumber="SS"+LocalDate.now().format(DateTimeFormatter.BASIC_ISO_DATE)+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT);CustomerOrder order=orders.save(new CustomerOrder(orderNumber,user,idempotencyKey,subtotal,0,0,address));
 for(List<CartItem> sellerLines:grouped.values()){Seller seller=sellerLines.get(0).getListing().getSeller();long sellerSubtotal=0;for(CartItem line:sellerLines)sellerSubtotal=Math.addExact(sellerSubtotal,Math.multiplyExact(line.getListing().getPriceMinor(),line.getQuantity()));SellerOrder sellerOrder=sellerOrders.save(new SellerOrder(order,seller,sellerSubtotal,0));for(CartItem line:sellerLines){Listing listing=line.getListing();Inventory stock=inventory.findByListingIdForUpdate(listing.getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"Inventory is unavailable"));try{stock.reserve(line.getQuantity());}catch(IllegalArgumentException ex){throw new ResponseStatusException(HttpStatus.CONFLICT,ex.getMessage());}movements.save(new InventoryMovement(stock,"RESERVED",-line.getQuantity(),"Reserved for order "+orderNumber,user));orderItems.save(new OrderItem(sellerOrder,listing,line.getQuantity()));}}
 String paymentKey=stablePaymentKey(userId,idempotencyKey);Payment payment=payments.save(new Payment(order,subtotal,"INR",paymentKey));PaymentIntent intent=gateway.createIntent(orderNumber,subtotal,"INR",paymentKey);payment.markPending(intent.provider(),intent.providerReference());events.save(new OrderEvent(order,null,"PAYMENT_PENDING",user,"Order created; inventory reserved pending payment"));cartItems.deleteAllByCart_Id(cart.getId());return response(order,payment,intent.checkoutUrl());}
 private CheckoutOrderResponse existingResponse(CustomerOrder order){Payment payment=payments.findByOrder_Id(order.getId()).orElseThrow(()->new IllegalStateException("Order payment record is missing"));String url=null;if("PENDING".equals(payment.getStatus())&&!order.isExpired(Instant.now()))url=gateway.createIntent(order.getOrderNumber(),payment.getAmountMinor(),payment.getCurrency(),payment.getIdempotencyKey()).checkoutUrl();return response(order,payment,url);}
 private CheckoutOrderResponse response(CustomerOrder order,Payment payment,String url){return new CheckoutOrderResponse(order.getOrderNumber(),order.getStatus(),order.getSubtotalMinor(),order.getShippingMinor(),order.getTotalMinor(),payment.getProvider(),payment.getStatus(),url,order.getExpiresAt());}
 private String stablePaymentKey(UUID userId,String key){try{byte[] hash=MessageDigest.getInstance("SHA-256").digest((userId+":"+key).getBytes(StandardCharsets.UTF_8));return HexFormat.of().formatHex(hash);}catch(Exception e){throw new IllegalStateException("Unable to create payment idempotency key",e);}}
}
